<?php
$rootPrefix='../';$pageTitle='My account | Moleqra';$pageRobots='noindex,nofollow';require_once __DIR__.'/../includes/bootstrap.php';require_once __DIR__.'/../includes/account_auth.php';require_once __DIR__.'/../includes/customer_security.php';$user=customer_user();if(!$user){header('Location: login.php');exit;}$pdo=db();$orders=[];$verified=true;if($pdo&&commerce_schema_ready($pdo)){$s=$pdo->prepare('SELECT order_number,order_token,status,payment_status,fulfilment_status,grand_total,currency,created_at FROM sales_orders WHERE customer_id=:id ORDER BY created_at DESC');$s->execute(['id'=>$user['id']]);$orders=$s->fetchAll();if(customer_security_ready($pdo))$verified=customer_email_verified($pdo,(int)$user['id']);}require __DIR__.'/../includes/header.php';?>
<section class="page-hero"><div class="container"><div class="eyebrow">Customer account</div><h1>Hello, <?= e($user['first_name']) ?></h1><p><?= e($user['email']) ?></p></div></section><section class="section"><div class="container"><?php if(isset($_GET['registered'])):?><div class="alert success">Account created. A verification message has been requested if outbound email is configured.</div><?php endif;?><?php if(!$verified):?><div class="alert error"><strong>Email not verified.</strong> <a href="resend-verification.php">Send another verification link</a>.</div><?php endif;?><div class="admin-heading"><div><h2>Your orders</h2><p><a href="addresses.php">Manage saved addresses</a></p></div><form method="post" action="logout.php"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><button class="btn">Sign out</button></form></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Order</th><th>Date</th><th>Payment</th><th>Fulfilment</th><th>Total</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><a href="../order.php?token=<?= e($o['order_token']) ?>"><?= e($o['order_number']) ?></a></td><td><?= e($o['created_at']) ?></td><td><?= e($o['payment_status']) ?></td><td><?= e($o['fulfilment_status']) ?></td><td><?= e($o['currency']) ?> <?= number_format((float)$o['grand_total'],2) ?></td></tr><?php endforeach;?><?php if(!$orders):?><tr><td colspan="5">No orders yet.</td></tr><?php endif;?></tbody></table></div></div></section><?php require __DIR__.'/../includes/footer.php';?>
